  'extends Node',
  '',
  'var manifest: Dictionary = {}',
  'var _assets_by_id: Dictionary = {}',
  'var _vfx_pools: Dictionary = {}',
  'var _vfx_scenes: Dictionary = {}',
  'var _audio_streams: Dictionary = {}',
  '',
  'func load_manifest(path: String) -> Dictionary:',
  '\tvar text := FileAccess.get_file_as_string(path)',
  '\tvar parsed = JSON.parse_string(text)',
  '\tif typeof(parsed) == TYPE_DICTIONARY:',
  '\t\tmanifest = parsed',
  '\t\t_assets_by_id.clear()',
  '\t\tfor entry in manifest.get("assets", []):',
  '\t\t\t_assets_by_id[entry.get("id", "")] = entry',
  '\treturn manifest',
  '',
  'func load_json_doc(path: String) -> Dictionary:',
  '\tvar parsed = JSON.parse_string(FileAccess.get_file_as_string(path))',
  '\treturn parsed if typeof(parsed) == TYPE_DICTIONARY else {}',
  '',
  'func register_vfx_scene(vfx_id: String, scene_res: PackedScene) -> void:',
  '\t_vfx_scenes[vfx_id] = scene_res',
  '',
  'func register_audio_stream(sound_id: String, stream: AudioStream) -> void:',
  '\t_audio_streams[sound_id] = stream',
  '',
  'func prewarm_vfx_pool(vfx_id: String, scene_res: PackedScene, count: int) -> void:',
  '\tregister_vfx_scene(vfx_id, scene_res)',
  '\tvar pool: Array = _vfx_pools.get(vfx_id, [])',
  '\tfor i in range(count):',
  '\t\tvar node := scene_res.instantiate()',
  '\t\tnode.visible = false',
  '\t\tadd_child(node)',
  '\t\tpool.append(node)',
  '\t_vfx_pools[vfx_id] = pool',
  '',
  'func spawn_vfx(vfx_id: String, anchor: Node3D) -> Node3D:',
  '\tvar instance: Node3D = null',
  '\tvar pool: Array = _vfx_pools.get(vfx_id, [])',
  '\tif pool.size() > 0:',
  '\t\tinstance = pool.pop_back()',
  '\t\tif instance.get_parent():',
  '\t\t\tinstance.get_parent().remove_child(instance)',
  '\telif _vfx_scenes.has(vfx_id):',
  '\t\tinstance = (_vfx_scenes[vfx_id] as PackedScene).instantiate()',
  '\tif instance == null:',
  '\t\treturn null',
  '\t(anchor if anchor != null else self).add_child(instance)',
  '\tinstance.position = Vector3.ZERO',
  '\tinstance.visible = true',
  '\treturn instance',
  '',
  'func recycle_vfx(vfx_id: String, instance: Node3D) -> void:',
  '\tif instance == null:',
  '\t\treturn',
  '\tinstance.visible = false',
  '\tif instance.get_parent():',
  '\t\tinstance.get_parent().remove_child(instance)',
  '\tadd_child(instance)',
  '\tvar pool: Array = _vfx_pools.get(vfx_id, [])',
  '\tpool.append(instance)',
  '\t_vfx_pools[vfx_id] = pool',
  '',
  'func configure_audio_player(sound_id: String, player: AudioStreamPlayer3D) -> bool:',
  '\tif player == null or not _audio_streams.has(sound_id):',
  '\t\treturn false',
  '\tvar stream: AudioStream = _audio_streams[sound_id]',
  '\tvar entry: Dictionary = _assets_by_id.get(sound_id, {})',
  '\tvar variants: Array = entry.get("variants", [])',
  '\tif variants.size() > 0:',
  '\t\tvar v: Dictionary = variants[0]',
  '\t\tvar sr: float = float(v.get("sampleRate", 48000))',
  '\t\tvar playback: Dictionary = v.get("playback", {})',
  '\t\tvar is_loop: bool = playback.get("kind", "oneshot") == "loop"',
  '\t\tvar loop_start: int = int(v.get("loopStartSample", 0))',
  '\t\tvar loop_end: int = int(v.get("loopEndSample", 0))',
