  '\tadd_child(actor)',
  '\tvar entry: Dictionary = _assets_by_id.get(asset_id, {})',
  '\tvar colliders: Dictionary = hooks_doc.get("colliders", entry.get("colliders", {}))',
  '\tactor.setup(self, asset_id, hooks_doc, colliders)',
