  'extends Node3D',
  '',
  'signal cue_triggered(cue_name: String, world_position: Vector3, payload: Dictionary)',
  '',
  'var asset_id: String = ""',
  'var anchors: Dictionary = {}',
  'var hooks: Dictionary = {}',
  'var _runtime: AshfoxRuntime = null',
  'var _anim_player: AnimationPlayer = null',
  'var _audio_player: AudioStreamPlayer3D = null',
  '',
  'func setup(runtime: AshfoxRuntime, id: String, hooks_doc: Dictionary, colliders: Dictionary) -> void:',
  '\t_runtime = runtime',
  '\tasset_id = id',
  '\thooks = hooks_doc',
  '\t_anim_player = _find_animation_player(self)',
  '\t_audio_player = AudioStreamPlayer3D.new()',
  '\tadd_child(_audio_player)',
  '\t_collect_anchors(hooks_doc)',
  '\t_attach_colliders(colliders)',
  '',
  'func get_anchor(anchor_id: String) -> Node3D:',
  '\treturn anchors.get(anchor_id, self)',
  '',
  'func play(clip_name: String) -> void:',
