  '\t\t_anim_player.play(clip_name)',
  '',
  'func trigger_vfx_cue(vfx_id: String, anchor_id: String = "") -> Node3D:',
  '\tif _runtime == null:',
  '\t\treturn null',
  '\treturn _runtime.spawn_vfx(vfx_id, get_anchor(anchor_id))',
  '',
  'func trigger_sound_cue(sound_id: String, anchor_id: String = "") -> bool:',
