  '\tvar anchor := get_anchor(anchor_id)',
  '\tcue_triggered.emit(cue_name, anchor.global_position, payload)',
  '',
  'func _find_animation_player(root: Node) -> AnimationPlayer:',
  '\tif root is AnimationPlayer:',
  '\t\treturn root',
  '\tfor child in root.get_children():',
  '\t\tvar found := _find_animation_player(child)',
  '\t\tif found != null:',
  '\t\t\treturn found',
  '\treturn null',
  '',
  'func _collect_anchors(hooks_doc: Dictionary) -> void:',
  '\tanchors.clear()',
  '\t_scan_anchor_nodes(self)',
  '\tfor decl in hooks_doc.get("anchors", []):',
  '\t\tvar aid: String = str(decl.get("id", ""))',
  '\t\tif aid.is_empty() or anchors.has(aid):',
  '\t\t\tcontinue',
  '\t\tvar marker := Marker3D.new()',
  '\t\tmarker.name = "anchor_" + aid',
  '\t\tvar pos: Array = decl.get("position", [0.0, 0.0, 0.0])',
  '\t\tif pos.size() == 3:',
  '\t\t\tmarker.position = Vector3(float(pos[0]) / 16.0, float(pos[1]) / 16.0, float(pos[2]) / 16.0)',
  '\t\tadd_child(marker)',
  '\t\tanchors[aid] = marker',
  '',
  'func _scan_anchor_nodes(node: Node) -> void:',
  '\tif node is Node3D and node.name.begins_with("anchor_"):',
  '\t\tvar marker := Marker3D.new()',
  '\t\tmarker.name = node.name + "_marker"',
  '\t\tnode.add_child(marker)',
  '\t\tanchors[node.name.substr(7)] = marker',
  '\tfor child in node.get_children():',
  '\t\t_scan_anchor_nodes(child)',
  '',
  'func _attach_colliders(colliders: Dictionary) -> void:',
  '\tvar list: Array = colliders.get("colliders", [])',
  '\tif list.is_empty():',
  '\t\treturn',
  '\tvar body := StaticBody3D.new()',
  '\tbody.name = "AshfoxColliders"',
  '\tadd_child(body)',
  '\tfor item in list:',
  '\t\tvar shape_node := CollisionShape3D.new()',
  '\t\tvar center: Array = item.get("center", [0.0, 0.0, 0.0])',
