const emitGodotSdk = (options?: SdkGenerationOptions): readonly GeneratedSdkFile[] => {
  const manifestComment = options?.manifest
    ? `# Manifest assets (${options.manifest.assets.length}): ${options.manifest.assets.map((a) => a.id).join(', ')}\n`
    : '';
  return Object.freeze([
    Object.freeze({
      target: 'godot',
      fileName: 'ashfox_runtime.gd',
      content: manifestComment + GODOT_RUNTIME_LINES.join('\n') + '\n',
    }),
    Object.freeze({
      target: 'godot',
      fileName: 'ashfox_actor.gd',
      content: GODOT_ACTOR_LINES.join('\n') + '\n',
    }),
  ]);
};

export const GODOT_SDK_STRATEGY: SdkTargetStrategy = Object.freeze({
  target: 'godot',
  files: emitGodotSdk,
});
